args.old_string:
/**
 * Balance snapshot cache. Folding the full stream on every read is expensive,
 * so the cache is refreshed at most once every REFRESH_EVERY events and reused
 * in between. The cached balances always correspond to a fold performed at
 * `atCount` events; between refreshes the cache may lag the stream by up to
 * REFRESH_EVERY - 1 events.
 */
const REFRESH_EVERY = 8

let cache = null

export function getBalance(ledger, account) {
  if (cache === null || ledger.eventCount() >= cache.atCount + REFRESH_EVERY) {
    cache = { atCount: ledger.eventCount(), balances: ledger.fold() }
  }
  return cache.balances[account] ?? 0
}

export function resetSnapshotCache() {
  cache = null
}

args.new_string:
/**
 * Balance snapshots are isolated per ledger and reused only while the event
 * stream is unchanged. This preserves exact reads without repeatedly folding
 * an unchanged stream.
 */
let caches = new WeakMap()

export function getBalance(ledger, account) {
  const eventCount = ledger.eventCount()
  let cache = caches.get(ledger)

  if (cache === undefined || cache.atCount !== eventCount) {
    cache = { atCount: eventCount, balances: ledger.fold() }
    caches.set(ledger, cache)
  }

  return cache.balances[account] ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

args.old_string:
export function transfer(ledger, from, to, amountCents, hooks = {}) {
  if (amountCents <= 0) throw new Error('amount must be positive')
  const balance = getBalance(ledger, from)
  if (balance < amountCents) throw new Error('insufficient funds')
  const ts = hooks.clock?.() ?? Date.now()
  ledger.append({ type: 'debit', account: from, amountCents, ts, id: hooks.nextId?.() ?? `evt-${ledger.eventCount()}` })
  ledger.append({ type: 'credit', account: to, amountCents, ts, id: hooks.nextId?.() ?? `evt-${ledger.eventCount()}` })
  hooks.onSettled?.({ from, to, amountCents, ts })
  return true
}

args.new_string:
export function transfer(ledger, from, to, amountCents, hooks = {}) {
  if (!Number.isSafeInteger(amountCents) || amountCents <= 0) {
    throw new Error('amount must be a positive safe integer')
  }

  const balance = getBalance(ledger, from)
  if (balance < amountCents) throw new Error('insufficient funds')

  // Resolve all caller-provided metadata before appending either half so an
  // exception cannot leave a lone debit in the event stream.
  const ts = hooks.clock?.() ?? Date.now()
  const debitId = hooks.nextId?.() ?? `evt-${ledger.eventCount()}`
  const creditId = hooks.nextId?.() ?? `evt-${ledger.eventCount() + 1}`

  ledger.append({ type: 'debit', account: from, amountCents, ts, id: debitId })
  ledger.append({ type: 'credit', account: to, amountCents, ts, id: creditId })
  hooks.onSettled?.({ from, to, amountCents, ts })
  return true
}

