@'
import assert from 'node:assert/strict'
import { createLedger, transfer, getBalance, resetSnapshotCache, createRebateHook } from './src/index.js'

const funded = (alice = 100) => {
  const ledger = createLedger()
  ledger.append({ type: 'credit', account: 'alice', amountCents: alice, ts: 1, id: 'fund' })
  return ledger
}

resetSnapshotCache()
const stale = funded()
assert.equal(getBalance(stale, 'alice'), 100)
transfer(stale, 'alice', 'bob', 80)
assert.equal(getBalance(stale, 'alice'), 20)
assert.throws(() => transfer(stale, 'alice', 'bob', 30), /insufficient/)
assert.deepEqual(stale.fold(), { alice: 20, bob: 80 })

const other = funded(700)
assert.equal(getBalance(other, 'alice'), 700)
assert.equal(getBalance(stale, 'alice'), 20)

const exposed = stale.events()
exposed[0].amountCents = 999999
assert.deepEqual(stale.fold(), { alice: 20, bob: 80 })
assert.equal(getBalance(stale, 'alice'), 20)

for (const amount of [NaN, Infinity, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  const ledger = funded()
  assert.throws(() => transfer(ledger, 'alice', 'bob', amount), /amount must be positive/)
  assert.equal(ledger.eventCount(), 1)
}

const atomic = funded()
let ids = 0
assert.throws(() => transfer(atomic, 'alice', 'bob', 10, { nextId: () => {
  if (++ids === 2) throw new Error('id failure')
  return 'first'
} }), /id failure/)
assert.equal(atomic.eventCount(), 1)
assert.deepEqual(atomic.fold(), { alice: 100 })

const rebateLedger = funded(10000)
rebateLedger.append({ type: 'credit', account: 'bob', amountCents: 5000, ts: 1, id: 'fund-bob' })
transfer(rebateLedger, 'alice', 'bob', 1000, { onSettled: createRebateHook(rebateLedger, 10) })
assert.deepEqual(rebateLedger.fold(), { alice: 9091, bob: 5909 })
assert.equal(getBalance(rebateLedger, 'alice'), 9091)
assert.equal(getBalance(rebateLedger, 'bob'), 5909)
assert.equal(Object.values(rebateLedger.fold()).reduce((a, b) => a + b, 0), 15000)

console.log('targeted invariant checks passed')
